--- Special regex-based rules for multi-number and mid-number modifiers
ModTranslationsRU.specialRules = {
    {
        pattern = "^Critical%s+Strikes%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+Blind%s+Enemies%s+while%s+you%s+have%s+Cat's%s+Stealth$",
        replacement = "Критические удары имеют %1 шанс ослепить врагов, пока на вас действует Кошачья скрытность",
    },
    {
        pattern = "^Basic%s+Currency%s+Items%s+dropped%s+by%s+slain%s+Enemies%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+be%s+Duplicated$",
        replacement = "Выпадающая из убитых врагов простая валюта с %1 шансом может быть продублирована",
    },
    {
        pattern = "^Divination%s+Cards%s+dropped%s+by%s+slain%s+Enemies%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+be%s+Duplicated$",
        replacement = "Выпадающие из убитых врагов гадальные карты с %1 шансом могут быть продублированы",
    },
    {
        pattern = "^Maps%s+dropped%s+by%s+slain%s+Enemies%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+be%s+Duplicated$",
        replacement = "Выпадающие из убитых врагов карты с %1 могут быть продублированы",
    },
    {
        pattern = "^Scarabs%s+dropped%s+by%s+slain%s+Enemies%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+be%s+Duplicated$",
        replacement = "Выпадающие из убитых врагов скарабеи с %1 шансом могут быть продублированы",
    },
    {
        pattern = "^Unique%s+Items%s+dropped%s+by%s+slain%s+Enemies%s+have%s+([%+%-]?%(?[%d%.%-–]+%)?%%?)%s+chance%s+to%s+be%s+Duplicated$",
        replacement = "Выпадающие из убитых врагов уникальные предметы с %1 шансом могут быть продублированы",
    },
